//! 🎟️ Exact native page effects and retained scalar writes use the same neutral original-grant corpus.
use super::*;
fn close<T:semio_framework_value_retirement::retirement::RetireOwned>(value:T,items:usize){use semio_framework_value_retirement::retirement::controlled::ControlledRetirement;let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));for _ in 0..2_000_000{if owner.terminal_is_empty(){return;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let step=crate::effect::settle(RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()},&mut None,|effect|owner.step(effect)).result.unwrap();assert!(step.progress().copied_items<=items);}panic!("retained work owner did not close");}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn neutral_font_ledger_matches_scalar_reference_and_physical_admission(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut values=PagedList::<i64,{usize::MAX}>::new();let mut reference=Vec::new();for value in fixture["values"].as_array().unwrap(){let value=value.as_i64().unwrap();for turn in 0..100{let d=RetainedWorkLedger::slot_demand(&values).unwrap();let original=grant(d);let mut partials=vec![RetainedCloneGrant{maximum_items:0,..original},RetainedCloneGrant{maximum_depth:d.depth-1,..original}];if d.capacity_bytes>0{partials.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..original});}if d.copy_bytes>0{partials.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..original});}for partial in partials{let ((ready,receipt),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(partial);let ready=work.slot(&mut values,&mut None).unwrap();(ready,work.receipt())});assert!(!ready);assert_eq!(receipt.retained_capacity_bytes,0);assert_eq!(receipt.copied_bytes,0);assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);}let ((ready,receipt),physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(original);let ready=work.slot(&mut values,&mut None).unwrap();if ready{work.push(&mut values,value).unwrap();}(ready,work.receipt())});assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,receipt.released_bytes);assert!(receipt.fits(original));if ready{reference.push(value);break;}assert!(turn<99);}}assert_eq!(values.iter().copied().collect::<Vec<_>>(),reference);close(values,1);}
#[test]fn unfinished_font_payload_holds_debit_only_committed_copies(){let mut first=PagedList::<i64,{usize::MAX}>::new();let mut second=PagedList::<i64,{usize::MAX}>::new();for values in [&mut first,&mut second]{while !values.has_reserved_slot(){let demand=RetainedWorkLedger::slot_demand(values).unwrap();let mut work=RetainedWorkLedger::new(grant(demand));assert!(!work.slot(values,&mut None).unwrap());}}let mut partial=RetainedWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1});assert!(partial.slot(&mut first,&mut None).unwrap());assert!(!partial.slot(&mut second,&mut None).unwrap());assert_eq!(partial.receipt().copied_bytes,0);assert_eq!(partial.next_demand().copy_bytes,16);let mut both=RetainedWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:16,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1});assert!(both.slot(&mut first,&mut None).unwrap());assert!(both.slot(&mut second,&mut None).unwrap());both.push(&mut first,5).unwrap();both.push(&mut second,9).unwrap();assert_eq!(both.receipt().copied_bytes,16);assert_eq!(both.remaining().maximum_copy_bytes,0);close(first,1);close(second,1);}

#[test]fn neutral_contiguous_font_source_admission_preserves_original_allocation(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let target=fixture["materializationValues"].as_u64().unwrap()as usize;let mut values=Vec::<u64>::new();let bytes=target*std::mem::size_of::<u64>();let mut denied=RetainedWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:bytes-1,maximum_release_bytes:0,maximum_depth:1});assert!(!denied.contiguous(&mut values,target,&mut None).unwrap());assert_eq!(values.capacity(),0);assert_eq!(denied.receipt().retained_capacity_bytes,0);let(receipt,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1});assert!(!work.contiguous(&mut values,target,&mut None).unwrap());work.receipt()});assert_eq!(physical.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(physical.released_bytes,0);assert_eq!(values.len(),0);assert_eq!(values.capacity(),target);close(values,1);}

#[test]fn neutral_string_admission_and_payload_are_independently_funded(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let source=fixture["text"].as_str().unwrap();let mut value=String::new();let demand=RetirementDemand{capacity_bytes:source.len(),depth:1,..Default::default()};
 let mut denied=RetainedWorkLedger::new(grant(RetirementDemand{capacity_bytes:source.len()-1,..demand}));assert!(!denied.reserve_string(&mut value,source.len(),&mut None).unwrap());assert_eq!(value.capacity(),0);assert_eq!(denied.receipt(),RetainedCloneProgress::default());
 let ((ready,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(grant(demand));let ready=work.reserve_string(&mut value,source.len(),&mut None).unwrap();(ready,work.receipt())});assert!(!ready);assert_eq!(heap.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(heap.released_bytes,receipt.released_bytes);assert!(value.is_empty());
 let mut denied=RetainedWorkLedger::new(grant(RetirementDemand{copy_bytes:source.len()-1,depth:1,..Default::default()}));assert!(!denied.string_push(&mut value,source).unwrap());assert!(value.is_empty());
 let mut work=RetainedWorkLedger::new(grant(RetirementDemand{copy_bytes:source.len(),depth:1,..Default::default()}));assert!(work.string_push(&mut value,source).unwrap());assert_eq!(work.receipt().copied_bytes,source.len());assert_eq!(value,source);close(value,1);
}
#[test]fn neutral_shared_owner_birth_uses_original_capacity_and_copy(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let payload=fixture["values"][0].as_i64().unwrap();let bytes=semio_framework_value_retirement::retirement::arc_custody::arc_bytes::<i64>();let demand=semio_framework_value_retirement::retirement::arc_custody::shared_allocation_value_demand::<i64>().unwrap();
 let mut denied=RetainedWorkLedger::new(grant(RetirementDemand{capacity_bytes:bytes-1,..demand}));assert!(!denied.arc_ready::<i64>().unwrap());assert_eq!(denied.receipt(),RetainedCloneProgress::default());
 let ((value,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(grant(demand));assert!(work.arc_ready::<i64>().unwrap());let value=work.arc_new(payload,&mut None).unwrap();(value,work.receipt())});assert_eq!(*value,payload);assert_eq!(heap.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(heap.released_bytes,receipt.released_bytes);close(semio_framework_value_retirement::retirement::arc_custody::SharedControlledRetirement::new(value),1);
}

#[test]fn neutral_vector_replacement_quotes_every_positive_axis_before_heap_effects(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let reference:Vec<i64>=fixture["values"].as_array().unwrap().iter().map(|value|value.as_i64().unwrap()).collect();let mut values=reference.clone();let target=values.capacity()+1;let demand=RetirementDemand{copy_bytes:values.len()*size_of::<i64>(),capacity_bytes:target*size_of::<i64>(),release_bytes:values.capacity()*size_of::<i64>(),depth:1};let original=grant(demand);
 let denied=[RetainedCloneGrant{maximum_items:0,..original},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..original},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..original},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..original},RetainedCloneGrant{maximum_depth:0,..original}];
 for partial in denied{let ((ready,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(partial);let ready=work.reserve_vec(&mut values,target,&mut None).unwrap();(ready,work.receipt())});assert!(!heap.overflowed);assert!(!ready);assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap.requested_bytes,0);assert_eq!(heap.released_bytes,0);assert_eq!(values,reference);}
 let ((ready,receipt,second),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(original);let ready=work.reserve_vec(&mut values,target,&mut None).unwrap();let receipt=work.receipt();let second=work.reserve_vec(&mut values,target+1,&mut None).unwrap();(ready,receipt,second)});assert!(!heap.overflowed);assert!(!ready);assert!(!second);assert_eq!(receipt.copied_bytes,demand.copy_bytes);assert_eq!(heap.requested_bytes,receipt.retained_capacity_bytes);assert_eq!(heap.released_bytes,receipt.released_bytes);assert_eq!(values,reference);close(values,1);
}

#[test]fn nested_contiguous_payload_requires_its_actual_depth_before_mutation(){
 let mut values=Vec::<u64>::with_capacity(1);let original=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<u64>(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};
 let ((ready,receipt,demand),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(original);let root=work.enter().unwrap();let ready=work.vec_slot(&mut values).unwrap();if ready{work.vec_push(&mut values,7).unwrap();work.note_source(root);}work.exit();(ready,work.receipt(),work.next_demand())});assert!(!ready);assert!(!heap.overflowed);assert_eq!(receipt,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(demand.depth,2);assert!(values.is_empty());
 let mut work=RetainedWorkLedger::new(RetainedCloneGrant{maximum_depth:2,..original});let root=work.enter().unwrap();assert!(work.vec_slot(&mut values).unwrap());work.vec_push(&mut values,7).unwrap();work.note_source(root);work.exit();assert_eq!(work.receipt().copied_bytes,size_of::<u64>());assert_eq!(values,[7]);close(values,1);
}

#[test]fn nested_cached_absolute_demand_keeps_parent_holds_and_depth_stable(){
 let law:serde_json::Value=serde_json::from_str(include_str!("absolute/🔣️.json")).unwrap();let mut parent_values=Vec::<u64>::with_capacity(1);let mut values=PagedList::<u64,{usize::MAX}>::new();
 let discovery=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<u64>(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:2};
 let ((demand,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(discovery);work.enter().unwrap();assert!(work.vec_slot(&mut parent_values).unwrap());work.enter().unwrap();assert!(!work.slot(&mut values,&mut None).unwrap());let d=work.next_demand();work.exit();work.exit();(d,work.receipt())});assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(receipt,Default::default());assert!(demand.depth>2);assert!(demand.capacity_bytes>0);assert!(demand.copy_bytes>=size_of::<u64>());
 for _ in 0..law["repeatedDenials"].as_u64().unwrap(){let original=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth-1};let((quote,receipt),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(original);work.enter().unwrap();assert!(work.vec_slot(&mut parent_values).unwrap());work.enter().unwrap();assert!(!work.admits_absolute(demand));work.require_absolute(demand);let quote=work.next_demand();work.exit();work.exit();(quote,work.receipt())});assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(receipt,Default::default());assert_eq!(quote,demand);assert!(parent_values.is_empty());}
 let original=grant(demand);let ((receipt,next),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut work=RetainedWorkLedger::new(original);work.enter().unwrap();assert!(work.vec_slot(&mut parent_values).unwrap());work.enter().unwrap();assert!(work.admits_absolute(demand),"absolute copy includes the existing parent hold once");assert!(!work.slot(&mut values,&mut None).unwrap());let receipt=work.receipt();let next=work.next_demand();work.exit();work.exit();(receipt,next)});assert!(!heap.overflowed);assert!(receipt.retained_capacity_bytes>0);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(original));assert!(next.depth>0);close((values,parent_values),1);
}

#[test]
fn shared_work_preserves_actual_null_and_same_ledger_retry(){
 use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();
 let input=law["text"].as_str().unwrap().to_owned();let pointer=input.as_ptr();let width=semio_framework_value_retirement::retirement::arc_custody::shared_allocation_value_demand::<String>().unwrap().copy_bytes;let bytes=semio_framework_value_retirement::retirement::arc_custody::shared_allocation_bytes::<String>();
 let original=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:width,maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1};
 let mut ledger=RetainedWorkLedger::new(original);
 let((result,attempts),heap)=observe(||refuse(||ledger.arc_new(input,&mut None)));
 assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(ledger.actual_work(),law["attemptWork"].as_u64().unwrap());assert_eq!(ledger.receipt(),Default::default());
 let(_,input)=result.unwrap_err();assert_eq!(input.as_ptr(),pointer);assert_eq!(serde_json::to_value(&input).unwrap(),law["text"]);
 let(result,heap)=observe(||ledger.arc_new(input,&mut None));let value=result.unwrap();assert_eq!(ledger.actual_work(),law["retryCpuStock"].as_u64().unwrap());assert_eq!(value.as_ptr(),pointer);assert_eq!(serde_json::to_value(&*value).unwrap(),law["text"]);assert_eq!(heap,(bytes,0));assert_eq!(ledger.receipt().retained_capacity_bytes,bytes);assert_eq!(ledger.receipt().copied_bytes,width);assert!(ledger.receipt().fits(original));
 close(semio_framework_value_retirement::retirement::arc_custody::SharedControlledRetirement::new(value),1);
}
#[test]
fn retained_storage_work_records_allocations_and_writes_without_charging_holds_or_cache(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let mut values=Vec::<u64>::new();
 let mut denied=RetainedWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()});assert!(!denied.contiguous(&mut values,1,&mut None).unwrap());assert_eq!(denied.actual_work(),law["deniedWork"].as_u64().unwrap());
 let g=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:8,maximum_capacity_bytes:8,maximum_depth:1,..Default::default()};
 let mut ledger=RetainedWorkLedger::new(g);assert!(!ledger.contiguous(&mut values,1,&mut None).unwrap());assert_eq!(ledger.actual_work(),1);assert!(ledger.contiguous(&mut values,1,&mut None).unwrap());assert_eq!(ledger.actual_work(),1);assert!(ledger.vec_slot(&mut values).unwrap());assert_eq!(ledger.actual_work(),1);ledger.vec_push(&mut values,42).unwrap();assert_eq!(ledger.actual_work(),2);assert_eq!(serde_json::to_value(&values).unwrap(),serde_json::json!([42]));close(values,1);
 let mut pages=PagedList::<u64,{usize::MAX}>::new();for _ in 0..100{let d=RetainedWorkLedger::slot_demand(&pages).unwrap();let mut ledger=RetainedWorkLedger::new(grant(d));let ready=ledger.slot(&mut pages,&mut None).unwrap();if ready{assert_eq!(ledger.actual_work(),law["heldWork"].as_u64().unwrap());ledger.push(&mut pages,42).unwrap();assert_eq!(ledger.actual_work(),law["writeWork"].as_u64().unwrap());break;}assert_eq!(ledger.actual_work(),law["attemptWork"].as_u64().unwrap());}assert_eq!(pages.iter().copied().collect::<Vec<_>>(),[42]);close(pages,1);
}
